-
-  RefPtr<nsDocShellLoadState> loadState = new nsDocShellLoadState(messageUri);
+  RefPtr<nsDocShellLoadState> loadState = new nsDocShellLoadState(uri);
   loadState->SetLoadFlags(nsIWebNavigation::LOAD_FLAGS_NONE);
